```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.05) p05_ms FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.05) FROM normal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY ALL",
          "claim": "search's client spans to geo.Geo/Nearby rose from about 0.4 ms p50 to about 1630 ms p50; geo's server spans stayed about 0.12 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, span_name, count(*) n, round(approx_quantile(duration/1e6,0.5),1) p50_ms, round(max(duration/1e6),1) max_ms FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "search's geo client calls stay about 1.6 s p50 every minute, while its rate client calls stay near 5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT trace_id, service_name, span_name, attr_span_kind, time, duration/1e6 ms FROM abnormal_traces WHERE trace_id='91ee21682fb9c72ceb6f8a0d0d3ed234' ORDER BY time",
          "claim": "In one trace, geo's server span starts about 3.1 s after search's geo client span, then runs 0.13 ms; the wait is before geo receives the request."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "frontend's /hotels HTTP span p95 is about 3095 ms, matching the search.Search/Nearby call it makes, versus about 13 ms normal."
        }
      ]
    }
  ]
}
```

